import{_ as t,o,c as i,ag as a}from"./chunks/framework.CbQjVMS6.js";const u=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1794023466000}'),r={name:"privacy.md"};function s(n,e,l,d,c,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><strong>Effective date:</strong> 6 November 2026<br><strong>Last updated:</strong> 7 November 2026</p><p>This policy explains how PieTeams (“we”, “us”) handles information when you visit <strong><a href="https://pieteams.github.io" target="_blank" rel="noreferrer">https://pieteams.github.io</a></strong> and the project documentation hosted under paths such as <code>/piekbs/</code>, <code>/piemdm/</code> and <code>/pieplm/</code> (together, “the Site”).</p><p>The Site is a documentation and open-source project website. You do not need an account to read it, and we do not ask you to submit personal information in order to use it.</p><h2 id="_1-who-is-responsible" tabindex="-1">1. Who is responsible <a class="header-anchor" href="#_1-who-is-responsible" aria-label="Permalink to &quot;1. Who is responsible&quot;">​</a></h2><p>The Site is published by the PieTeams open-source project. For privacy questions, contact us through the website repository:</p><p><a href="https://github.com/pieteams/pieteams.github.io/issues" target="_blank" rel="noreferrer">github.com/pieteams/pieteams.github.io/issues</a></p><h2 id="_2-information-we-process" tabindex="-1">2. Information we process <a class="header-anchor" href="#_2-information-we-process" aria-label="Permalink to &quot;2. Information we process&quot;">​</a></h2><h3 id="information-you-provide" tabindex="-1">Information you provide <a class="header-anchor" href="#information-you-provide" aria-label="Permalink to &quot;Information you provide&quot;">​</a></h3><p>The Site has no account system, comment system or contact form. If you open an issue or pull request on GitHub, the information you submit is processed by GitHub under <a href="https://docs.github.com/en/site-policy/privacy-policies/github-privacy-statement" target="_blank" rel="noreferrer">GitHub&#39;s privacy statement</a>, not by us. We see the content you choose to publish there.</p><h3 id="information-collected-automatically" tabindex="-1">Information collected automatically <a class="header-anchor" href="#information-collected-automatically" aria-label="Permalink to &quot;Information collected automatically&quot;">​</a></h3><p>When you load a page, the following technical information may be processed:</p><ul><li>the requested URL, the time of the request and the referring page</li><li>an approximate location derived from the IP address (normally at city or country level)</li><li>browser type, operating system, device type and screen size</li><li>IP address, which is processed by our hosting provider to deliver the page and protect the service</li></ul><p>We do not attempt to identify individual readers from this data.</p><h3 id="cookies-and-similar-technologies" tabindex="-1">Cookies and similar technologies <a class="header-anchor" href="#cookies-and-similar-technologies" aria-label="Permalink to &quot;Cookies and similar technologies&quot;">​</a></h3><p>Cookies are small text files stored by your browser. The Site and its third-party services may set the following categories:</p><table tabindex="0"><thead><tr><th>Category</th><th>Purpose</th><th>Set by</th><th>Typical duration</th></tr></thead><tbody><tr><td>Essential</td><td>Deliver the page and its assets; remember theme and language preferences</td><td>GitHub Pages, VitePress</td><td>Session to 1 year</td></tr><tr><td>Advertising</td><td>Select, deliver and measure ads; limit repeated ads; detect invalid traffic</td><td>Google AdSense and its partners</td><td>Up to 2 years, depending on the cookie</td></tr></tbody></table><p>You can delete or block cookies in your browser settings. Blocking advertising cookies does not prevent you from reading the documentation.</p><h2 id="_3-analytics" tabindex="-1">3. Analytics <a class="header-anchor" href="#_3-analytics" aria-label="Permalink to &quot;3. Analytics&quot;">​</a></h2><p>The Site does not currently use a third-party analytics service. If we introduce one, we will update this policy, list the service and its cookies in the table above, and — where required — obtain consent before it is enabled.</p><h2 id="_4-advertising" tabindex="-1">4. Advertising <a class="header-anchor" href="#_4-advertising" aria-label="Permalink to &quot;4. Advertising&quot;">​</a></h2><p>The Site displays advertising served by <strong>Google AdSense</strong>.</p><ul><li>Third-party vendors, including Google, use cookies to serve ads based on a user&#39;s prior visits to this website or other websites.</li><li>Google&#39;s use of advertising cookies enables it and its partners to serve ads to users based on their visits to this Site and/or other sites on the Internet.</li><li>Users may opt out of personalised advertising by visiting <a href="https://www.google.com/settings/ads" target="_blank" rel="noreferrer">Google Ads Settings</a>.</li><li>Users may also opt out of a third-party vendor&#39;s use of cookies for personalised advertising by visiting <a href="https://www.aboutads.info/choices/" target="_blank" rel="noreferrer">www.aboutads.info/choices</a>.</li></ul><p>Where required by applicable law, we rely on consent for advertising cookies. You can withdraw consent at any time by clearing or blocking cookies in your browser settings, or by using the opt-out links above. Advertising supports the hosting and maintenance of the Site. Advertisers do not review or approve our documentation, and advertising does not influence technical comparisons or recommendations.</p><p>Google&#39;s <a href="https://support.google.com/adspolicy/answer/6008942" target="_blank" rel="noreferrer">Advertising Policies</a> and <a href="https://policies.google.com/technologies/ads" target="_blank" rel="noreferrer">How Google uses cookies in advertising</a> provide further information.</p><h2 id="_5-legal-bases-eea-uk-and-switzerland" tabindex="-1">5. Legal bases (EEA, UK and Switzerland) <a class="header-anchor" href="#_5-legal-bases-eea-uk-and-switzerland" aria-label="Permalink to &quot;5. Legal bases (EEA, UK and Switzerland)&quot;">​</a></h2><p>Where the General Data Protection Regulation applies, we rely on the following legal bases:</p><ul><li><strong>Legitimate interests</strong> for operating and securing the Site, and for aggregate measurement needed to maintain documentation quality.</li><li><strong>Consent</strong> for advertising cookies where consent is required, and for any processing that is not covered by legitimate interests.</li><li><strong>Legal obligation</strong> where we must retain or disclose information to comply with applicable law.</li></ul><p>You may object to processing based on legitimate interests, and withdraw consent at any time, using the contact method below.</p><h2 id="_6-sharing-and-disclosure" tabindex="-1">6. Sharing and disclosure <a class="header-anchor" href="#_6-sharing-and-disclosure" aria-label="Permalink to &quot;6. Sharing and disclosure&quot;">​</a></h2><p>We do not sell personal information. We do not rent or trade reader data.</p><p>Information may be processed by the following service providers for the purposes described above:</p><ul><li><strong>GitHub Pages</strong> — static hosting and content delivery</li><li><strong>Google AdSense</strong> — advertising delivery and measurement</li></ul><p>These providers process data under their own terms and privacy policies. We may also disclose information if required by law, or to protect the rights, safety and security of the Site, its maintainers or its users.</p><h2 id="_7-international-transfers" tabindex="-1">7. International transfers <a class="header-anchor" href="#_7-international-transfers" aria-label="Permalink to &quot;7. International transfers&quot;">​</a></h2><p>The Site is served by GitHub, and advertising is provided by Google. These providers may process information in countries other than the one in which you live. Where required, transfers are covered by the providers&#39; standard contractual clauses or equivalent safeguards. See the providers&#39; privacy documentation for details.</p><h2 id="_8-retention" tabindex="-1">8. Retention <a class="header-anchor" href="#_8-retention" aria-label="Permalink to &quot;8. Retention&quot;">​</a></h2><p>We do not maintain our own database of reader information. Advertising and hosting logs are retained by the relevant provider according to its own policies. GitHub issue content remains publicly available until it is edited or removed.</p><h2 id="_9-your-rights" tabindex="-1">9. Your rights <a class="header-anchor" href="#_9-your-rights" aria-label="Permalink to &quot;9. Your rights&quot;">​</a></h2><p>Depending on your location, you may have the right to:</p><ul><li>access the personal information we hold about you</li><li>request correction or deletion</li><li>restrict or object to processing</li><li>withdraw consent</li><li>request data portability</li><li>lodge a complaint with a supervisory authority</li></ul><p>Because we do not operate a reader account system, we may not be able to identify you in our records. In that case we will explain what we can and cannot do. To make a request, use the contact method below.</p><p><strong>California residents:</strong> we do not sell or share personal information for cross-context behavioural advertising in the sense of the CCPA/CPRA beyond the advertising cookies described above. You can opt out of personalised advertising using the links in section 4.</p><h2 id="_10-children" tabindex="-1">10. Children <a class="header-anchor" href="#_10-children" aria-label="Permalink to &quot;10. Children&quot;">​</a></h2><p>The Site is intended for a technical audience and is not directed at children under 16. We do not knowingly collect personal information from children. If you believe a child has provided personal information, contact us so that it can be removed.</p><h2 id="_11-security" tabindex="-1">11. Security <a class="header-anchor" href="#_11-security" aria-label="Permalink to &quot;11. Security&quot;">​</a></h2><p>The Site is served over HTTPS from GitHub Pages. We do not store reader credentials or payment information. No method of transmission or storage is completely secure, and we cannot guarantee absolute security.</p><h2 id="_12-external-links" tabindex="-1">12. External links <a class="header-anchor" href="#_12-external-links" aria-label="Permalink to &quot;12. External links&quot;">​</a></h2><p>The documentation links to third-party websites, repositories and products. Their privacy practices are outside our control. Review their policies before providing personal information.</p><h2 id="_13-changes-to-this-policy" tabindex="-1">13. Changes to this policy <a class="header-anchor" href="#_13-changes-to-this-policy" aria-label="Permalink to &quot;13. Changes to this policy&quot;">​</a></h2><p>We may update this policy to reflect changes in the Site, the services we use or applicable law. The effective date at the top of the page will be updated. Material changes will be noted in the website repository. Continued use of the Site after an update means you accept the revised policy.</p><h2 id="_14-contact" tabindex="-1">14. Contact <a class="header-anchor" href="#_14-contact" aria-label="Permalink to &quot;14. Contact&quot;">​</a></h2><p>For privacy questions or requests:</p><p><a href="https://github.com/pieteams/pieteams.github.io/issues" target="_blank" rel="noreferrer">github.com/pieteams/pieteams.github.io/issues</a></p><p>Please describe your request and the page or service involved. We will respond as quickly as we reasonably can.</p>',55)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
